config.code:
CREATE TABLE inbox (
    seq INTEGER PRIMARY KEY, update_id INTEGER NOT NULL UNIQUE,
    payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', received_at INTEGER NOT NULL
);
CREATE TABLE actions (
    action_key TEXT PRIMARY KEY, method TEXT NOT NULL,
    state TEXT NOT NULL, result TEXT, created_at INTEGER NOT NULL
);

CREATE TABLE connections (
    id TEXT PRIMARY KEY, owner_id INTEGER NOT NULL, enabled INTEGER NOT NULL,
    can_reply INTEGER NOT NULL, checked_at INTEGER NOT NULL
);
CREATE TABLE conversations (
    connection_id TEXT NOT NULL, chat_id INTEGER NOT NULL,
    mode TEXT NOT NULL DEFAULT 'auto', last_incoming INTEGER,
    PRIMARY KEY(connection_id,chat_id)
);
CREATE TABLE business_log (
    id INTEGER PRIMARY KEY, connection_id TEXT NOT NULL, chat_id INTEGER,
    message_id INTEGER, event TEXT NOT NULL, created_at INTEGER NOT NULL
);
